#include <stdio.h>

int main() {
    long long val;
    long long mn = 0, mx = 0, sum = 0;
    int count = 0;
    while (scanf("%lld", &val) == 1 && val != -1) {
        if (count == 0) {
            mn = mx = val;
        } else {
            if (val < mn) mn = val;
            if (val > mx) mx = val;
        }
        sum += val;
        count++;
    }
    if (count > 0) {
        printf("Min = %lld\nMax = %lld\nSum = %lld\nAverage = %.6f\n", mn, mx, sum, (double)sum / count);
    }
    return 0;
}

