code.Java:
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long mn = 0, mx = 0, sum = 0;
        int count = 0;
        while (sc.hasNextLong()) {
            long val = sc.nextLong();
            if (val == -1) break;
            if (count == 0) { mn = mx = val; }
            else {
                if (val < mn) mn = val;
                if (val > mx) mx = val;
            }
            sum += val;
            count++;
        }
        if (count > 0) {
            System.out.printf("Min = %d\nMax = %d\nSum = %d\nAverage = %.6f\n", mn, mx, sum, (double)sum / count);
        }
    }
}

code.JavaScript:
const fs = require('fs');
function main() {
    const parts = fs.readFileSync(0, 'utf-8').trim().split(/\s+/);
    const nums = [];
    for (const p of parts) {
        const v = parseInt(p, 10);
        if (v === -1) break;
        nums.push(v);
    }
    if (nums.length > 0) {
        const mn = Math.min(...nums);
        const mx = Math.max(...nums);
        const s = nums.reduce((a, b) => a + b, 0);
        const avg = s / nums.length;
        console.log(`Min = ${mn}`);
        console.log(`Max = ${mx}`);
        console.log(`Sum = ${s}`);
        console.log(`Average = ${avg.toFixed(6)}`);
    }
}
main();

